<?php
declare(strict_types=1);
namespace AIcontrol;
use AIcontrolWorkspaceUi as Ui;
final class ResearchView
{
    private static function dashboard(array $project,?array $snapshot): void
    {
        $usage=$snapshot['usage']['project']??$project['usage'];
        echo '<section class="research-now" data-research-now><div class="research-now-heading"><div><div class="research-eyebrow">CURRENT FINDINGS</div><h2>'.Ui::e($project['name']).' · current findings</h2></div><p data-project-spend>'.Ui::e(UsageMeter::label($usage)).' · '.number_format($usage['total_tokens']).' tokens'.($usage['reserved_usd']>0?' · $'.number_format($usage['reserved_usd'],4).' reserved':'').'</p></div><ul data-current-findings>';
        foreach($snapshot['findings']??[['text'=>'Start an investigation to collect evidence.','status'=>'not started','reason'=>'No findings yet.','provisional'=>true]] as $finding)echo '<li><strong>'.Ui::e(ucfirst($finding['status']).($finding['provisional']?' · provisional':'')).': </strong>'.Ui::e($finding['text'].' '.$finding['reason']).'</li>';
        echo '</ul><div class="research-live" data-live-activity role="status">'.($snapshot?'Saved state: '.Ui::e($snapshot['run']['status'].' · '.$snapshot['run']['phase']).'. Reload to refresh without JavaScript.':'Ready when you are.').'</div><small data-live-clock aria-live="off"></small></section>';
    }
    private static function settings(array $project,string $csrf): void
    {
        echo '<form class="research-settings" method="post" action="/loader.php?view=research" data-research-action="research_settings">'.$csrf.'<input type="hidden" name="action" value="research_settings"><input type="hidden" name="project_id" value="'.(int)$project['id'].'"><h3>Research pace and model budget</h3><label for="research-primary-model">High-impact and verification model</label><select class="form-select" id="research-primary-model" name="primary_model">';
        foreach(['gpt-4.1'=>'GPT-4.1 · higher-quality priority paths','gpt-4.1-mini'=>'GPT-4.1 mini · lower-cost priority paths'] as $model=>$label)echo '<option value="'.$model.'"'.($project['primary_model']===$model?' selected':'').'>'.$label.'</option>';
        echo '</select>';if(getenv('AICONTROL_OPENAI_MODEL'))echo '<p>Server override: '.Ui::e((string)getenv('AICONTROL_OPENAI_MODEL')).' controls the primary model.</p>';echo '<label for="research-spend-cap">Tracked project spend cap (USD)</label><input class="form-control" id="research-spend-cap" name="spend_cap_usd" type="number" min="0.05" max="1000" step="0.01" value="'.Ui::e((string)$project['spend_cap_usd']).'" required><label for="research-growth">Additional searches for new questions</label><select id="research-growth" name="growth_searches" class="form-select">';
        for($i=0;$i<=3;$i++)echo '<option value="'.$i.'"'.((int)$project['growth_searches']===$i?' selected':'').'>'.$i.'</option>';
        echo '</select><label class="form-check"><input class="form-check-input" type="checkbox" name="auto_search" value="1"'.((int)$project['auto_search']?' checked':'').'><span>Automatically research ranked paths after claim review</span></label><p>One specialist request at a time; '.UsageMeter::hourlyLimit().' requests/hour shared across research. Lower-ranked searches use GPT-4.1 mini; unconventional questions use GPT-4.1 nano. At most two creative passes, twelve new questions and six searches per investigation. Model and pace settings apply to new runs; the spend cap applies immediately.</p><p>The cap includes tracked estimates and reserved maximum request costs. Historical unpriced calls, invoice adjustments and taxes are not included. Unknown outcomes keep their reservation.</p><button class="btn btn-primary">Save research settings</button></form>';
    }
    private static function paths(array $snapshot,string $csrf): void
    {
        foreach($snapshot['nodes'] as $node)if(in_array($node['type'],['dream_claim','question'],true)){
            $id=(int)$node['id'];echo '<article data-speculative="'.(int)$node['speculative'].'"><h4>'.Ui::e($node['title']).'</h4><p>Priority '.(int)$node['path_weight'].' · '.Ui::e($node['model_tier']).' model tier · '.Ui::e($node['speculative']?'Untested idea — may be wrong.':$node['weight_reason']).'</p>';
            $direct=UsageMeter::summary(array_values(array_filter($snapshot['requests'],static fn(array $q):bool=>(int)($q['path_node_id']??0)===$id)));echo '<p>Direct path searches: '.Ui::e(UsageMeter::label($direct)).' · '.$direct['total_tokens'].' tokens</p>';
            if($node['type']==='question')echo '<p>'.Ui::e($node['content']).'</p>';
            if((int)$snapshot['run']['flow_version']===1&&$snapshot['run']['status']==='running'&&$snapshot['run']['busy_since']===null&&(int)$node['selected']===1){
                echo '<form class="path-priority-form" method="post" action="/loader.php?view=research" data-research-action="research_rank">'.$csrf.'<input type="hidden" name="action" value="research_rank"><input type="hidden" name="run_id" value="'.(int)$snapshot['run']['id'].'"><input type="hidden" name="node_id" value="'.$id.'"><label>Priority weight<input class="form-control" type="number" name="path_weight" min="10" max="100" value="'.(int)$node['path_weight'].'"></label><label>Model budget<select name="model_tier" class="form-select"><option value="primary"'.($node['model_tier']==='primary'?' selected':'').'>Automatic by priority</option><option value="economy"'.($node['model_tier']==='economy'?' selected':'').'>Economy · GPT-4.1 mini</option></select></label><button class="btn btn-outline-primary">Update path priority</button></form>';
            }
            echo '</article>';
        }
    }
    private static function usage(array $snapshot): void
    {
        $usage=$snapshot['usage'];
        echo '<details class="research-usage"><summary>Tokens &amp; spend · '.Ui::e(UsageMeter::label($usage['project'])).'</summary><p data-usage-total>'.Ui::e(UsageMeter::label($usage['project'])).' · '.number_format($usage['project']['input_tokens']).' input / '.number_format($usage['project']['output_tokens']).' output tokens · $'.number_format($usage['project']['reserved_usd'],4).' reserved or uncertain risk · $'.number_format($usage['cap_usd'],2).' cap</p><p>USD estimates from returned API usage and saved pricing checked '.UsageMeter::CHECKED.'. Cached input is part of input; reasoning tokens are part of output. Shared planning, mapping, verification and Learn are not silently attributed to a single path. <a href="'.UsageMeter::SOURCE.'" target="_blank" rel="noopener noreferrer">Official pricing</a></p><div data-usage-areas>';
        foreach($usage['areas'] as $area)echo '<p>'.Ui::e($area['title']).' · weight '.$area['weight'].' · '.Ui::e(UsageMeter::label($area['usage'])).' · '.$area['usage']['total_tokens'].' tokens</p>';
        echo '</div><div class="usage-table-scroll" tabindex="0" role="region" aria-label="Provider usage table"><table class="table"><caption>Provider requests in this investigation</caption><thead><tr><th scope="col">Role / area</th><th scope="col">Model</th><th scope="col">Input</th><th scope="col">Cached</th><th scope="col">Output</th><th scope="col">Searches</th><th scope="col">USD estimate</th><th scope="col">State</th></tr></thead><tbody data-usage-requests>';
        foreach($snapshot['requests'] as $request)echo '<tr><th scope="row">'.Ui::e(($request['worker_role']??$request['kind']).($request['claim_id']?' · claim #'.$request['claim_id']:' · shared')).'</th><td>'.Ui::e($request['model']??'Historical model unknown').'</td><td>'.($request['token_input']??'Unknown').'</td><td>'.($request['cached_tokens']??'Unknown').'</td><td>'.($request['token_output']??'Unknown').'</td><td>'.($request['tool_calls']??'Unknown').'</td><td>'.($request['estimated_usd']===null?'Unknown':'$'.number_format((float)$request['estimated_usd'],6)).'</td><td>'.Ui::e($request['status']).'</td></tr>';
        echo '</tbody></table></div><div data-usage-groups></div></details>';
    }
    private static function form(string $csrf,string $action,int $run,string $label,string $class='btn-primary',bool $disabled=false):string
    {
        return '<form method="post" action="/loader.php?view=research" data-research-action="'.$action.'">'.$csrf.'<input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="run_id" value="'.$run.'"><button class="btn '.$class.'"'.($disabled?' disabled':'').'>'.$label.'</button></form>';
