    public static function nodes(array $nodes,?int $parent=null):void
    {
        foreach($nodes as $node)if($node['type']!=='learn' && (($node['parent_id']===null?null:(int)$node['parent_id'])===$parent)){
            echo '<details class="investigation-node" data-node-id="'.(int)$node['id'].'" data-status="'.Ui::e($node['status']).'" open><summary><span>'.Ui::e($node['title']).'</span> <small>'.Ui::e($node['type'].' · '.$node['status']).'</small></summary><div class="node-content">'.Ui::e($node['content']).'</div><div class="node-children">';
            self::nodes($nodes,(int)$node['id']);echo '</div></details>';
        }
    }
    public static function sources(array $sources,array $passages=[]):void
    {
        foreach($sources as $source){
            if(!Investigation::sourceUrl($source['url']))continue;
            echo '<article class="research-source" data-source-id="'.(int)$source['id'].'"><div class="source-domain"><span class="source-monogram" aria-hidden="true">'.Ui::e(strtoupper(substr($source['domain'],0,1))).'</span>'.Ui::e($source['domain']).' · Cited source</div><h4>Source #'.(int)$source['id'].' · '.Ui::e($source['title']).'</h4><a href="'.Ui::e($source['url']).'" target="_blank" rel="noopener noreferrer">'.Ui::e($source['url']).'</a><p>'.Ui::e($source['extract']).'</p><small>'.Ui::e($source['domain']).' · Citation captured '.Ui::e(Ui::time((int)$source['retrieved_at'])).'</small>';
            echo '<section data-source-passages><h5>Captured passages</h5>';
            $found=false;foreach($passages as $passage)if((int)$passage['source_id']===(int)$source['id']){$found=true;self::passage($passage);}if(!$found)echo '<p>No captured source passage. Citation-only material.</p>';echo '<p>'.Ui::e($source['shared_origin']??'Source independence not assessed.').'</p></section></article>';
        }
    }
    public static function claimSources(array $snapshot, int $claim): array
    {
        $parents=[]; foreach ($snapshot['nodes'] as $node) $parents[(int)$node['id']]=$node['parent_id'];
        return array_values(array_filter($snapshot['sources'], static function(array $source) use ($parents,$claim,$snapshot): bool {
            foreach($snapshot['ledger']['edges']??[] as $edge)if((int)$edge['claim_id']===$claim&&(int)$edge['source_id']===(int)$source['id'])return true;
            $meta=json_decode($source['meta_json']??'{}',true)??[];
            if (in_array($claim,array_map('intval',$meta['claim_ids']??[]),true)) return true;
            $id=(int)$source['node_id']; $seen=[];
            while ($id && !isset($seen[$id])) { if ($id===$claim) return true; $seen[$id]=true; $id=(int)($parents[$id]??0); }
            return false;
        }));
    }
    public static function board(array $snapshot): void
    {
        foreach ($snapshot['nodes'] as $claim) if ($claim['type']==='dream_claim') {
            $data=Investigation::claimData($claim);$id=(int)$claim['id'];
            echo '<article class="dream-card" data-claim-id="'.$id.'"><div class="claim-number">PRIOR / '.str_pad((string)$id,2,'0',STR_PAD_LEFT).'</div><label class="claim-selection"><input type="checkbox" name="claim_ids[]" value="'.$id.'"'.((int)($claim['selected']??1)?' checked':'').'><span>Include claim #'.$id.'</span></label><h4>'.Ui::e($data['claim']).'</h4><p class="claim-badges"><span class="claim-badge" data-confidence="'.Ui::e($data['confidence']).'">'.Ui::e(ucfirst($data['confidence'])).' prior confidence</span>'.($data['priority']==='high'?'<span class="claim-badge">High priority</span>':'').'</p><p><strong>Uncertainty: </strong>'.Ui::e($data['uncertainty']).'</p><p><strong>Verify: </strong>'.Ui::e($data['verify']).'</p>';
            if (!(int)($claim['selected']??1)) echo '<p>Excluded from verification</p>';
            echo '<div class="claim-trail">';
            $descendants=[$id];foreach($snapshot['nodes'] as $node) if(in_array((int)$node['parent_id'],$descendants,true)) {$descendants[]=(int)$node['id'];if(in_array($node['type'],['plan_step','dead_end','synthesis'],true)) echo '<article class="claim-event" data-status="'.Ui::e($node['status']).'"><h5>'.($node['type']==='dead_end'?'⚑ Dead end · ':'').Ui::e($node['title']).'</h5><p>'.Ui::e($node['type']==='synthesis'?(json_decode($node['data_json']??'{}',true)['reason']??$node['content']):$node['content']).'</p></article>';}
            foreach(self::claimSources($snapshot,$id) as $source) {echo '<p class="source-relevance">Evidence collected to test claim #'.$id.'</p>';self::sources([$source],$snapshot['ledger']['passages']??[]);}
            echo '</div></article>';
        }
    }
    public static function matrix(array $snapshot): void
    {
        foreach($snapshot['nodes'] as $claim) if($claim['type']==='dream_claim') {
            $verdict=null;foreach($snapshot['nodes'] as $node)if((int)$node['parent_id']===(int)$claim['id']&&$node['type']==='synthesis')$verdict=$node;
            $data=json_decode($verdict['data_json']??'{}',true)??[];
            $outcome=$data['verdict']??($verdict?strtolower(explode(' · ',$verdict['title'])[0]):'open');
            if(!(int)($claim['selected']??1))$outcome='Excluded from verification';
            echo '<tr><th scope="row">'.Ui::e(Investigation::claimData($claim)['claim']).'</th><td>'.Ui::e(ucfirst($outcome)).'</td><td>';
            $sources=self::claimSources($snapshot,(int)$claim['id']);
            if(isset($data['source_ids']))$sources=array_filter($sources,static fn(array $source):bool=>in_array((int)$source['id'],$data['source_ids'],true));
            if(!$sources)echo 'No useful source';
            foreach($sources as $source)if(Investigation::sourceUrl($source['url']))echo '<a href="'.Ui::e($source['url']).'" target="_blank" rel="noopener noreferrer">'.Ui::e($source['title']).'</a> ';
            foreach($snapshot['ledger']['edges']??[] as $edge)if((int)$edge['claim_id']===(int)$claim['id']){echo '<details class="matrix-relation"><summary>'.Ui::e($edge['relation'].' · '.($edge['strength']??'unrated')).'</summary><p>'.Ui::e($edge['rationale']).'</p>';if($edge['passage_id']===null)echo '<p>Citation-only relation; no captured passage.</p>';foreach($snapshot['ledger']['passages'] as $passage)if((int)$passage['id']===(int)$edge['passage_id'])self::passage($passage);echo '</details>';}
            echo '</td></tr>';
        }
    }
    public static function budgetLabel(array $budget): string
    {
        $label=$budget['remaining'].' of '.($budget['limit']??10).' requests remaining this hour · shared across search, verification and Learn';
        if($budget['remaining']===0)$label.=' · Next request available in about '.(int)ceil($budget['retry_after_seconds']/60).' minutes';
        return $label;
    }
