    public static function ledger(array $snapshot,string $csrf): void
    {
        $ledger=$snapshot['ledger']??['edges'=>[],'passages'=>[],'claim_versions'=>[],'sources'=>[]];
        echo '<section class="evidence-ledger" data-evidence-ledger'.(!(int)($snapshot['run']['rigour_version']??0)&&!$ledger['edges']?' hidden':'').'><h3>Claim–evidence ledger</h3><p>Typed relations are model assessments, not proof. Captured snippets are not independently fetched or verified page text.</p><div data-ledger-entries>';
        foreach($ledger['edges'] as $edge){
            echo '<article class="ledger-edge"><h4>Claim #'.(int)$edge['claim_id'].' · '.Ui::e($edge['relation']).'</h4><p>'.Ui::e($edge['rationale']).'</p><small>'.Ui::e($edge['strength']??'Unrated').' strength · edge #'.(int)$edge['id'].'</small>';
            foreach($ledger['passages'] as $passage)if((int)$passage['id']===(int)$edge['passage_id'])self::passage($passage);
            if($edge['passage_id']===null)echo '<p>Citation-only relation — no captured source passage.</p>';
            foreach($ledger['sources'] as $source)if((int)$source['id']===(int)$edge['source_id']&&Investigation::sourceUrl($source['url']))echo '<a href="'.Ui::e($source['url']).'" target="_blank" rel="noopener noreferrer">'.Ui::e($source['title']).'</a><p>'.Ui::e($source['shared_origin']??'Independence not assessed.').'</p>';
            echo '</article>';
        }
        echo '</div><details><summary>Claim assessment history</summary><div data-ledger-history>';
        foreach($ledger['claim_versions'] as $version)echo '<p>Claim #'.(int)$version['claim_id'].' · '.Ui::e($version['status'].' · '.$version['created_by'].' · '.$version['rationale']).'</p>';
        echo '</div></details><details class="verification-panel"><summary>Verification findings</summary><div data-verification-results>';
        $high=false;
        foreach($snapshot['nodes'] as $node)if($node['type']==='phase'&&in_array($node['title'],['Verification','Repair'],true)){
            $data=json_decode($node['data_json'],true)??[];echo '<h4>'.Ui::e($node['title'].' · '.$node['status']).'</h4>';
            foreach($data['defects']??[] as $defect){if($node['title']==='Verification'&&$defect['severity']==='high')$high=true;echo '<p>'.Ui::e($defect['severity'].' · '.$defect['kind'].' · '.$defect['description']).'</p>';}
            foreach($data['calculations']??[] as $check)echo '<p>'.Ui::e('Arithmetic '.$check['operation'].' ('.$check['a'].', '.$check['b'].'): reported '.$check['reported'].'; expected '.($check['expected']??'undefined').' · '.($check['arithmetic_correct']?'passed':'failed').'. Operands still require source validation.').'</p>';
            if($node['status']==='complete'&&!($data['defects']??[]))echo '<p>No defects reported by the grouped model check. This is not independent source verification.</p>';
        }
        echo '</div></details><p data-ledger-freeze>'.((int)($snapshot['run']['evidence_frozen']??0)?'Frozen evidence version '.(int)$snapshot['run']['evidence_version']:'Evidence is still provisional.').'</p><div data-verification-controls'.($snapshot['run']['phase']!=='verification_review'||$snapshot['run']['status']!=='running'?' hidden':'').'>';
        echo self::form($csrf,'research_finish',(int)$snapshot['run']['id'],'Finish and freeze evidence');
        echo self::form($csrf,'research_repair',(int)$snapshot['run']['id'],'Review high-impact gaps once','btn-outline-secondary',!$high||(int)$snapshot['run']['repair_count']>0||$snapshot['budget']['remaining']<1);
        echo '<p>Finish uses no provider request. Optional repair uses one bounded request, has no search tools, and cannot retry an unknown outcome.</p></div></section>';
    }
    public static function passage(array $passage): void
    {
        echo '<details class="evidence-passage"><summary>Passage #'.(int)$passage['id'].' · '.Ui::e($passage['fetch_scope']).'</summary><blockquote>'.Ui::e($passage['exact_text']).'</blockquote><small>'.Ui::e($passage['locator']??'No locator supplied').' · SHA-256 '.Ui::e($passage['content_hash']).'</small></details>';
    }
    public static function render(array $data,string $csrf):void
    {
        $workspace=$data['workspace'];$project=$workspace['project'];$snapshot=$workspace['snapshot'];$run=$snapshot['run']??null;
        $review=$run && $run['status']==='running' && $run['phase']==='dream_review';
        $entry=$_SERVER['SCRIPT_NAME']??'/loader.php';
        if(!preg_match('~^/[A-Za-z0-9_./-]+\.php$~D',$entry))$entry='/loader.php';
        if($project)self::dashboard($project,$snapshot);
        echo '<details class="research-project-menu" data-project-menu'.(!$run?' open':'').'><summary>Project menu · projects, settings and history</summary>';
        echo '<p data-request-error class="research-error" role="alert"></p><div class="research-budget-notice" data-request-budget role="status">'.Ui::e(self::budgetLabel($workspace['budget'])).'</div>';
        if(!$project)echo '<section class="research-welcome card mb-3"><div class="card-body"><div class="research-eyebrow">YOUR RESEARCH NOTEBOOK</div><h2>Turn a question into evidence you can review</h2><p>An investigation proposes unchecked hypotheses, lets you choose what to verify, then collects sources and records what remains unresolved.</p><a class="btn btn-primary" href="#research-name">Create your first research project</a></div></section>';
        echo '<section class="card mb-3 research-project-picker"><div class="card-body"><div class="research-eyebrow">PROJECTS</div><div class="research-project-list">';
        foreach($data['projects'] as $p)echo '<a class="btn btn-outline-secondary" href="/loader.php?view=research&amp;project='.(int)$p['id'].'"'.($project && $p['id']===$project['id']?' aria-current="page"':'').'>'.Ui::e($p['name']).' · '.Ui::e(UsageMeter::label($p['usage'])).'</a>';
        echo '</div><details class="project-create"'.(!$project?' open':'').'><summary>Create a research project</summary><form method="post" action="/loader.php?view=research" class="mt-3">'.$csrf.'<input type="hidden" name="action" value="research_project"><label class="form-label" for="research-name">Research name</label><input id="research-name" name="name" class="form-control mb-3" maxlength="160" required><label class="form-label" for="research-brief">Research brief</label><textarea id="research-brief" name="brief" class="form-control mb-3" rows="3" maxlength="4000" aria-describedby="brief-guidance"></textarea><p id="brief-guidance" class="brief-guidance">Write a specific question, the place or timeframe that matters, and what evidence would change your mind. For example: Is rooftop solar worthwhile for a Perth household on current tariffs?</p><button class="btn btn-primary">Create research project</button></form></details></div></section>';
        if(!AgentRunner::configured())echo '<div class="alert alert-info">Connect OpenAI in <a href="/loader.php?view=admin">Admin</a> to start an investigation or chat. You can organise projects now.</div>';
        if(!$project){echo '</details>';return;}
        echo '<section class="card mb-3 research-project-brief"><div class="card-body"><h2>'.Ui::e($project['name']).'</h2><p class="text-break">'.Ui::e($project['brief']).'</p><details class="brief-help"><summary>What makes a useful investigation brief?</summary><p>Include the decision you face, relevant place or timeframe, and what would count as convincing evidence. Review these against the generated verification angles.</p></details><form method="post" action="/loader.php?view=research" data-research-action="research_start">'.$csrf.'<input type="hidden" name="action" value="research_start"><input type="hidden" name="project_id" value="'.(int)$project['id'].'"><button class="btn btn-primary"'.(!AgentRunner::configured()||($run&&in_array($run['status'],['pending','running'],true))?' disabled':'').'>Start research</button></form></div></section>';
        self::settings($project,$csrf);echo '<a href="#research-history">History and earlier chat</a></details>';
        if($run){
            $active=in_array($run['status'],['pending','running'],true);$pending=(bool)array_filter($snapshot['requests'],static fn(array $r):bool=>$r['status']==='pending');$busy=$run['busy_since']!==null;
            echo '<section class="card mb-3 investigation" data-investigation data-connected="'.(AgentRunner::configured()?'1':'0').'" data-phase="'.Ui::e($run['phase']).'" data-review="'.($review?'1':'0').'" data-entry="'.Ui::e($entry).'" data-run-id="'.(int)$run['id'].'" data-status="'.Ui::e($run['status']).'" data-busy="'.($busy?'1':'0').'"><div class="card-body"><div class="investigation-heading"><div><div class="research-eyebrow">RESEARCH WORKSPACE</div><h2>Investigation #'.(int)$run['id'].'</h2><p data-research-summary role="status" aria-live="polite">'.Ui::e($run['status'].' · '.($review?'Dream complete — review claims':$run['phase'])).' · '.(int)$run['token_input'].' input / '.(int)$run['token_output'].' output tokens confirmed'.($run['usage_unknown']?' · some usage unknown':'').'</p></div><div class="research-controls">';
            echo '<div data-stop-control'.(!$active&&!$pending?' hidden':'').'>'.self::form($csrf,'research_stop',(int)$run['id'],'Stop research','btn-outline-danger').'</div><div data-step-control'.(!$active||$busy||$review||$run['phase']==='verification_review'?' hidden':'').'>'.self::form($csrf,'research_step',(int)$run['id'],'Continue next phase','btn-outline-secondary').'</div>';
            echo self::form($csrf,'research_export',(int)$run['id'],'Export Markdown','btn-outline-secondary');
            echo '<div class="research-recovery" data-recovery'.(!in_array($run['status'],['interrupted','uncertain','incomplete','failed'],true)?' hidden':'').'><p>The saved claims, evidence and request status are retained. Calls already sent may still be billed; unknown outcomes are not retried.</p><form method="post" action="/loader.php?view=research" data-research-action="research_start">'.$csrf.'<input type="hidden" name="action" value="research_start"><input type="hidden" name="project_id" value="'.(int)$project['id'].'"><button class="btn btn-outline-primary">Start a new investigation from this project</button></form></div>';
            echo ''.'</div></div><p data-research-reason>'.Ui::e($run['stop_reason']).'</p><p class="research-error" data-research-error role="alert"></p><details class="research-run-notes"><summary>Usage &amp; Stop behavior</summary><p>Tokens are confirmed after each response. Stop prevents the next phase; an in-flight call may finish or be billed. Saved evidence remains available.</p></details><ol class="research-phase-rail" aria-label="Investigation stages" data-phase-rail>';
            $completed=array_column(array_filter($snapshot['nodes'],static fn(array $n):bool=>$n['type']==='phase'&&$n['status']==='complete'),'title');
            foreach(['dream'=>'01 · Dream','dream_review'=>'02 · Review','plan'=>'03 · Plan','evidence'=>'04 · Evidence',((int)$run['rigour_version']===1?'verification':'reconciliation')=>'05 · Findings'] as $phase=>$label){ $done=in_array(ucfirst($phase),$completed,true)||($phase==='dream_review'&&$run['phase']!=='dream'&&$run['phase']!=='dream_review');$target=in_array($phase,['dream','dream_review'],true)?'board':($phase==='reconciliation'?'outcomes':'tree');echo '<li data-phase="'.$phase.'"'.($done?' data-done="1"':'').($run['phase']===$phase?' aria-current="step"':'').'><a href="#research-'.$target.'"'.(!$done?' aria-disabled="true" tabindex="-1"':'').'>'.Ui::e($label).'</a></li>'; }
            echo '</ol><p class="research-live-progress" data-live-progress role="status"></p><div class="research-metrics" data-research-metrics><div><strong>'.count(array_filter($snapshot['nodes'],static fn(array $n):bool=>$n['type']==='dream_claim')).'</strong><span>prior claims</span></div><div><strong>'.count($snapshot['sources']).'</strong><span>collected sources</span></div><div><strong>'.Ui::e($run['status']).'</strong><span>run status</span></div></div><div class="research-subtabs"><a href="#investigate-'.(int)$run['id'].'">Investigate</a><a href="#learn-'.(int)$run['id'].'" data-learn-link'.(!$snapshot['sources']?' hidden':'').'>Learn</a></div><section id="investigate-'.(int)$run['id'].'">';self::mindMap($csrf,(int)$run['id']);echo '<div data-investigate-list>';self::usage($snapshot);echo '<details class="research-paths"><summary>Research paths · priority, model budget and untested questions</summary><p>Priority controls attention and model budget, not probability or evidence strength. High priority uses green; lower priority uses grey; purple dashed paths are untested ideas.</p><div data-research-paths>';self::paths($snapshot,$csrf);echo '</div></details>';self::ledger($snapshot,$csrf);echo '<section id="research-outcomes" data-claim-matrix'.($run['status']!=='complete'?' hidden':'').'><h3>Claim outcomes</h3><div class="claim-matrix-scroll"><table class="table"><thead><tr><th scope="col">Claim</th><th scope="col">Outcome</th><th scope="col">Key sources</th></tr></thead><tbody data-matrix-rows>';self::matrix($snapshot);echo '</tbody></table></div></section><div class="research-section-heading"><span class="research-eyebrow">CLAIMS &amp; EVIDENCE</span><p>Each claim starts as a hypothesis. Sources and findings appear beneath the claim they test.</p></div><section id="research-board" class="dream-board" aria-label="Dream claim board"><h3>Model’s prior — not yet checked</h3><p class="dream-empty" data-dream-empty'.(array_filter($snapshot['nodes'],static fn(array $n):bool=>$n['type']==='dream_claim')?' hidden':'').'>'.Ui::e($active&&$run['phase']==='dream'?'Generating prior hypotheses… Claims will appear as they are saved. No evidence has been established yet.':'No prior claims were saved. Inspect the saved status before starting again.').'</p><div class="dream-skeleton" data-dream-skeleton aria-hidden="true"'.($run['phase']!=='dream'||!$active?' hidden':'').'><span></span><span></span></div><p data-review-copy'.(!$review?' hidden':'').'>Choose what to verify. Uncheck weak claims, then continue. Unselected claims are excluded from Plan, Evidence and Reconciliation for this run; this selection cannot be changed after Continue.</p><form method="post" action="/loader.php?view=research" data-research-action="research_continue">'.$csrf.'<input type="hidden" name="action" value="research_continue"><input type="hidden" name="run_id" value="'.(int)$run['id'].'"><div class="review-shortcuts" data-review-shortcuts hidden><button type="button" class="btn btn-outline-secondary" data-keep="all">Keep all</button><button type="button" class="btn btn-outline-secondary" data-keep="priority">Keep high-priority only</button><button type="button" class="btn btn-outline-secondary" data-keep="confidence">Exclude low-confidence</button></div><div class="dream-grid" data-dream-cards>';self::board($snapshot);
            echo '</div><div class="claim-review-actions"><span data-selection-count aria-live="polite"></span><button class="btn btn-primary" data-continue-claims'.(!$review?' hidden':'').'>Continue with selected claims</button></div><noscript><p>Continue uses all claims when JavaScript is unavailable.</p></noscript></form><div class="prior-context" data-prior-context>';
            foreach($snapshot['nodes'] as $node){$context=json_decode($node['data_json']??'{}',true);if(isset($context['least_confident']))echo '<h4>Prior context</h4><p><strong>Competing angles: </strong>'.Ui::e(implode('; ',$context['competing_angles'])).'</p><p><strong>Least confident: </strong>'.Ui::e($context['least_confident']).'</p><p><strong>Background assumptions: </strong>'.Ui::e(implode('; ',$context['background_assumptions'])).'</p>';}
            echo '</div></section><details id="research-tree" class="full-research-tree"><summary>Full investigation tree</summary><div data-research-tree>';self::nodes($snapshot['nodes']);
            echo '</div></details><details class="source-catalog"><summary>Source library</summary><p>Links come from completed provider web-search citations. Summaries are model paraphrases, not independently verified quotations.</p><div data-research-sources>';self::sources($snapshot['sources'],$snapshot['ledger']['passages']??[]);echo '</div></details><p data-source-empty'.($snapshot['sources']?' hidden':'').'>No source cards collected yet. Learn becomes available once evidence exists.</p></div></section><section id="learn-'.(int)$run['id'].'" data-learn-panel'.(!$snapshot['sources']?' hidden':'').'><h3>Learn</h3><p>Uses only this run’s collected cards and project brief. No new web search or shared Admin notes are sent. Available after the investigation stops.</p><form method="post" action="/loader.php?view=research" data-research-action="research_learn">'.$csrf.'<input type="hidden" name="action" value="research_learn"><input type="hidden" name="run_id" value="'.(int)$run['id'].'"><label class="form-label" for="learn-action">Learning action</label><select id="learn-action" class="form-select mb-3" name="learn_action"><option value="explain">Explain findings</option><option value="caveats">Caveats and limitations</option><option value="compare">Compare sources</option><option value="deeper">Go deeper</option><option value="check">Check my understanding</option></select><label class="form-label" for="learn-question">Question or your understanding (optional)</label><textarea id="learn-question" name="question" class="form-control mb-3" rows="3" maxlength="2000"></textarea><button class="btn btn-primary" data-learn-submit'.($active||$pending||!AgentRunner::configured()?' disabled':'').'>Learn from collected evidence</button></form><div data-learn-results role="region" aria-label="Saved learning responses">';
            foreach($snapshot['nodes'] as $learn)if($learn['type']==='learn')echo '<article class="research-message" data-learning-id="'.(int)$learn['id'].'"><h4>'.Ui::e($learn['title'].' · '.$learn['status']).'</h4><p>'.Ui::e($learn['content']).'</p></article>';
            echo '</div><div data-learn-followups'.(!array_filter($snapshot['nodes'],static fn(array $n):bool=>$n['type']==='learn'&&$n['status']==='complete')?' hidden':'').'>';self::followups($csrf,(int)$run['id'],$active||$pending||!AgentRunner::configured());echo '</div></section></div></section>';
        } else { echo '<div class="alert alert-info">No investigation yet. Start research to build a visible tree of unchecked claims, searches, source cards and findings.</div>'; }
        if($workspace['runs']){
            echo '<details class="card mb-3" id="research-history"><summary class="card-body">Investigation history</summary><div class="card-body">';
            foreach($workspace['runs'] as $old)echo '<p><a href="/loader.php?view=research&amp;project='.(int)$project['id'].'&amp;run='.(int)$old['id'].'">Run #'.(int)$old['id'].' · '.Ui::e($old['status']).' · '.Ui::e(Ui::time((int)$old['started_at'])).'</a></p>';
            echo '</div></details>';
        }
        echo '<details class="card"><summary class="card-body">Simple chat and earlier conversations</summary><div class="card-body"><p>Legacy project chat remains available. Investigations and Learn share its request limit.</p><div class="research-conversation" role="region" aria-label="Earlier research conversation">';
        foreach($data['messages'] as $message)if((int)$message['project_id']===(int)$project['id']){
            echo '<article class="research-message"><h3>'.($message['role']==='user'?'You':'Research assistant').' · '.Ui::e($message['status']).'</h3><p>'.Ui::e($message['text']?:'Waiting for the provider outcome.').'</p>';
            if($message['status']==='pending' && (int)$message['created_at']<time()-120)echo '<form method="post" action="/loader.php?view=research">'.$csrf.'<input type="hidden" name="action" value="research_resolve"><input type="hidden" name="message_id" value="'.(int)$message['id'].'"><button class="btn btn-outline-secondary">Mark interrupted request as uncertain</button></form>';
            echo '</article>';
        }
        echo '</div><form method="post" action="/loader.php?view=research" data-research-chat>'.$csrf.'<input type="hidden" name="action" value="research_chat"><input type="hidden" name="project_id" value="'.(int)$project['id'].'"><label class="form-label" for="simple-research-message">Message</label><textarea id="simple-research-message" name="message" class="form-control mb-3" rows="3" maxlength="4000" required></textarea><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="web" value="1" checked><span class="form-check-label">Search the web for current sources (provider charges apply)</span></label><button class="btn btn-primary"'.(!AgentRunner::configured()?' disabled':'').'>Send research message</button><span class="ms-2" data-research-status role="status"></span></form></div></details>';
    }
}
